import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial, texture as texNode, float as floatNode, mul as mulNode } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @param {Object} config
 * @param {Object} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// ---------- Load assets ----------
	const srcImg = config.assets?.imageUrl ?? '';
	const srcDepth = config.assets?.depthMapUrl ?? '';

	const tex = ctx.textureLoader(srcImg);
	const depthTex = ctx.textureLoader(srcDepth);

	// ---------- Geometry ----------
	const geometry = new THREE.PlaneGeometry(2, 0.1, 64, 64);

	// ---------- Material (TSL) ----------
	const material = new MeshStandardNodeMaterial();
	material.colorNode = texNode(tex);
	// displacement = depth texture * scaleFactor
	const dispScale = 0.05; // subtle displacement
	material.displacementNode = mulNode(texNode(depthTex), floatNode(dispScale));
	material.displacementScaleNode = floatNode(1.0);
	material.transparent = true;

	const mesh = new THREE.Mesh(geometry, material);
	mesh.position.set(
		-1.25,
		-0.19999999999999996,
		0
	);
	mesh.rotation.set(0, 0, 0);
	mesh.scale.set(1, 1, 1);

	// ---------- Apply cinematic primitives from config ----------
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const fn = ctx.primitives?.[prim.name];
			if (typeof fn === 'function') {
				fn(mesh, prim.params);
			}
		}
	}

	// ---------- Ensure parallax effect ----------
	if (ctx.primitives?.['parallax-scroll']) {
		ctx.primitives['parallax-scroll'](mesh, { intensity: 0.1 });
	}

	// ---------- Interaction handlers ----------
	const hoverTL = gsap.timeline({ paused: true, defaults: { ease: 'power3.out', duration: 0.15 } });
	hoverTL.to(mesh.position, { y: mesh.position.y + 0.15 });

	const handlers = {
		hover: (event) => {
			if (event?.type === 'enter') {
				hoverTL.play();
			} else if (event?.type === 'leave') {
				hoverTL.reverse();
			}
		},
		click: () => {
			if (typeof ctx.emit === 'function') {
				ctx.emit('hub-features.select');
			}
		}
	};

	mesh.userData.handlers = handlers;

	// ---------- Cleanup ----------
	mesh.userData.cleanup = () => {
		hoverTL.kill();
		geometry.dispose();
		material.dispose();
		// textures are shared via ctx.loader; do not dispose here
	};

	return mesh;
}
